import{_ as t,o as a,c as s,a4 as o}from"./chunks/framework.C83Ss68L.js";const p=JSON.parse('{"title":"ADR-0002: Singleton facades exposed as use* functions","description":"Stateful services are Singleton classes with getInstance(), published to consumers as use* wrapper functions.","frontmatter":{"title":"ADR-0002: Singleton facades exposed as use* functions","description":"Stateful services are Singleton classes with getInstance(), published to consumers as use* wrapper functions."},"headers":[],"relativePath":"explanation/decisions/adr-0002-singleton-facades.md","filePath":"explanation/decisions/adr-0002-singleton-facades.md","lastUpdated":1791568280000}'),n={name:"explanation/decisions/adr-0002-singleton-facades.md"};function r(c,e,i,d,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0002-singleton-facades-exposed-as-use-functions" tabindex="-1">ADR-0002: Singleton facades exposed as <code>use*</code> functions <a class="header-anchor" href="#adr-0002-singleton-facades-exposed-as-use-functions" aria-label="Permalink to &quot;ADR-0002: Singleton facades exposed as `use*` functions&quot;">​</a></h1><p><strong>Status:</strong> Accepted · <strong>Date:</strong> 2026-10-04 (released in v6.5.0)</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Services own state: the API registry, the logger&#39;s level, the query cache, the active theme. A purely functional API would have to thread that state through arguments or hide it in module globals with no identity or lifecycle. A purely class-based API would force consumers to manage instances, break the tree-shakeable named-export style the library had shipped since v1, and add <code>new</code> boilerplate to every call. Earlier versions mixed both styles ad hoc — some services exported loose functions, others exported objects.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Every stateful service is a <strong>Singleton class</strong> — private constructor, <code>getInstance()</code> as the only entry — whose public methods use the <code>use*</code> prefix (<code>getInstance()</code> and the static <code>create()</code> are the exceptions). The module re-exports thin <code>use*</code> wrappers and destructured exports that delegate to the singleton, so consumers keep the functional API (<code>useLogger(...)</code>, <code>useFetch(...)</code>) while the class owns the state. Services that need isolated instances expose <code>create()</code> or an injectable strategy (storage backends, <code>AccessService</code>, <code>AgentService</code>). The configuration entry points follow the same shape: <code>define*Config</code> registers and returns the facade — the v6.0.0 rename of <code>useInit*</code> kept the principle and improved the name (<a href="/katanakit-js/guides/upgrade-to/v6">Upgrade to v6</a>).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Better.</strong> There is one obvious instance, a predictable naming rule, and the public API stays tree-shakeable and stable across the refactor. Tests can inject <code>create()</code> instances or mock the facade shape (the <a href="/katanakit-js/guides/services/http-client">HTTP Client</a> page shows the DI pattern) without stubbing globals.</p><p><strong>Worse.</strong> The <code>use*</code> prefix on plain functions reads as hooks to React developers and as an oddity to everyone else; contributors must remember that <code>getInstance()</code> and <code>create()</code> are deliberate exceptions. Singleton state is process-wide: on a long-lived server the API registry is shared across requests, so it must be treated as immutable after startup and per-request data passed through <code>params</code>, <code>query</code> or <code>headers</code>. And there are two ways to reach the same behavior — the wrapper and the class — deliberately kept for injection and backwards compatibility.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="/katanakit-js/guides/architecture">Architecture</a> — the pattern table across all services.</li><li><a href="/katanakit-js/guides/services/http-client">HTTP Client</a> — wrapper vs. <code>getInstance()</code> in practice.</li><li><a href="/katanakit-js/guides/upgrade-to/v6">Upgrade to v6</a> — the <code>useInit*</code> → <code>define*Config</code> rename.</li></ul>',11)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
